J evidence=J::array();
template<class F>void attempt(const std::string& name,F fn){try{J r=fn();r["name"]=name;r["accepted"]=true;evidence.push_back(r);}catch(const std::exception& e){evidence.push_back({{"name",name},{"accepted",false},{"exception",e.what()}});}}
void write_doc(const J& doc,const std::string& path){std::ofstream f(path);f<<doc.dump();if(!f)throw std::runtime_error("write probe");}
J read_doc(const std::string& path){J d;std::ifstream f(path);f>>d;if(!f)throw std::runtime_error("read probe");return d;}
void rehash(J& d,bool journal){auto& b=d["payload"];if(journal){std::string chain=b["metadata"]["journal"][0]["payload"]["previous_chain"];for(auto& row:b["metadata"]["journal"]){row["payload"]["previous_chain"]=chain;row["sha256"]=sha(row["payload"].dump());chain=row["sha256"];}b["metadata"]["chain"]=chain;}d["sha256"]=sha(b.dump());}
