 evidence.push_back({{"name","exclusive_owner_type_traits"},{"copy_constructible",std::is_copy_constructible_v<m::PicArena>},{"move_constructible",std::is_move_constructible_v<m::PicArena>}});
 attempt("copied_owner_forks_native_history",[&]{m::GapPic pic(options());m::GapParticle p;p.charge_C=0;p.mass_kg=mn;p.position_m={.004,.004,.0125};p.proper_velocity_m_s={1e4,0,0};auto ids=pic.add_authored_batch({p});pic.solve_fields();m::PicArena one(pic,states(),channels(),{{"n","H2O","authored","",{1,0},ids}},"copy/initial");m::PicArena two=one;auto first=one.prepare_transport(1e-12);if(!one.try_publish(first))throw std::runtime_error("first publication");auto second=two.prepare_transport(1e-12);if(!two.try_publish(second))throw std::runtime_error("second publication");return J{{"native_time_s",pic.diagnostics().time_s},{"first_owner_steps",one.snapshot()->accepted_steps},{"second_owner_steps",two.snapshot()->accepted_steps},{"second_journal",two.snapshot()->journal},{"two_owners_same_native",true}};});
