 auto tamper=[&](const std::string& name,const std::string& file,const std::string& initial,bool journal,auto change){attempt(name,[&]{auto doc=read_doc(input+"/"+file);change(doc["payload"]);rehash(doc,journal);auto path=out+"/"+name+".json";write_doc(doc,path);m::GapPic pic(options());auto restored=m::PicArena::restore(pic,path,states(),channels(),initial);return J{{"restored_steps",restored->snapshot()->accepted_steps},{"restored_sinks",restored->snapshot()->sinks},{"journal",restored->snapshot()->journal}};});};
